import os, json, time, subprocess, pathlib, hashlib, platform, statistics
root=pathlib.Path(__file__).resolve().parent
cases=['water-631g','hydroxide-631g','stretched-water-631g','water-dimer-631g']
modes=['direct','lda-coarse','pbe-coarse']
env=os.environ|dict(OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1',NUMEXPR_NUM_THREADS='1',PYTHONHASHSEED='0')
meta={'time_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'source_head':'8ba615aacd9f02708b39782cc71b68f27bbe1af6','source_tree':'42cc3f8f871523a4d48304f520a5e967e61cea6e','library_sha256':'670c81365bde477f32e5a7fc6af1cff5e489a42e118651aca77090fd00626258','target':'PBE0/RKS, 25% exact exchange + 75% PBE exchange + 100% PBE correlation','target_controls':{'energy_tolerance':1e-10,'density_tolerance':1e-8,'grid':[1,24,12,24,3,1e-12],'precision':'FP64','max_iterations':150,'compute_forces':False},'lda_pbe_seed_controls':{'energy_tolerance':1e-6,'density_tolerance':1e-4,'grid':[1,8,6,12,3,1e-12],'basis':'same as target','max_iterations':150},'xtb_seed_controls':{'energy_tolerance':1e-10,'charge_tolerance':1e-8,'max_iterations':100,'mapping':'existing charge_guided_lowdin_density; target core density; no naive cross-basis copy'},'threads':1,'thermal_definition':'First and second native endpoint in each fresh process. Both recreate all plans and grids; warm means process/library warm, not reused converged SCF or prepared plan. Process launch overhead excluded from endpoint and measured separately.','cpu_affinity_isolated':False,'cases':cases,'modes':modes,'repeats':3,'platform':platform.platform(),'harness_sha256':hashlib.sha256((root/'staged.cpp').read_bytes()).hexdigest(),'basis_sha256':hashlib.sha256((root/'basis.inc').read_bytes()).hexdigest(),'caveat':'Native internal energy-only endpoint with explicit same-basis seed handoff. Not a public CLI feature, force benchmark, GPU run, large system, or auto-promotion claim.'}
(root/'protocol.json').write_text(json.dumps(meta,indent=2))
rows=[]
with (root/'records.jsonl').open('w') as f:
 for repeat in range(3):
  for case in cases:
   order=modes[repeat:]+modes[:repeat]
   if repeat==1: order=list(reversed(order))
   for mode in order:
    start=time.perf_counter()
    p=subprocess.run([str(root/'staged'),case,mode],capture_output=True,text=True,env=env,timeout=90)
    wall=time.perf_counter()-start
    if p.returncode:
     r={'case':case,'mode':mode,'repeat':repeat,'failure':p.stderr,'process_wall_s':wall};rows.append(r);f.write(json.dumps(r)+'\n');f.flush();print(r,flush=True);continue
    for line in p.stdout.splitlines():
     r=json.loads(line);r['repeat']=repeat;r['process_wall_s']=wall;rows.append(r);f.write(json.dumps(r)+'\n');f.flush()
    print(case,mode,repeat,'cold',round(json.loads(p.stdout.splitlines()[0])['total_s'],4),'s',flush=True)
summary=[]
for case in cases:
 for thermal in ['process-cold','process-warm-fresh-context']:
  base=[r for r in rows if r['case']==case and r['mode']=='direct' and r.get('thermal')==thermal]
  if not base: continue
  for mode in modes:
   rr=[r for r in rows if r['case']==case and r['mode']==mode and r.get('thermal')==thermal]
   if not rr: continue
   pairs=[(r,next(b for b in base if b['repeat']==r['repeat'])) for r in rr]
   med=lambda k:statistics.median(r[k] for r in rr)
   deltae=max(abs(r['energy']-b['energy']) for r,b in pairs)
   deltad=max(max(abs(x-y) for x,y in zip(r['density'],b['density'])) for r,b in pairs)
   summary.append({'case':case,'thermal':thermal,'mode':mode,'n':len(rr),'target_iterations':sorted(set(r['target_iterations'] for r in rr)),'cheap_iterations':sorted(set(r['cheap_iterations'] for r in rr)),'target_fock_builds':sorted(set(r['target_fock_builds'] for r in rr)),'cheap_fock_builds':sorted(set(r['cheap_fock_builds'] for r in rr)),'median_total_s':med('total_s'),'median_prep_s':med('prep_s'),'median_target_scf_s':med('target_scf_s'),'median_common_setup_s':med('common_setup_s'),'total_ratio':med('total_s')/statistics.median(b['total_s'] for b in base),'max_energy_difference':deltae,'max_density_difference':deltad,'max_residual':max(r['residual'] for r in rr),'qualified_matched_state':deltae<1e-8 and deltad<1e-6 and max(r['residual'] for r in rr)<1e-8})
(root/'summary.json').write_text(json.dumps(summary,indent=2))
print('DONE',len(rows),'records',len([r for r in rows if 'failure' in r]),'failures',flush=True)
for r in summary:
 if r['thermal']=='process-cold':print({k:v for k,v in r.items() if k not in ['thermal']},flush=True)

