#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>
#include "dft/xc.hpp"
#include "methods/gfn2_runtime_bridge.hpp"
#include "molecule/basis.hpp"
#include "scf/fock_prepared.hpp"
#include "scf/initial_guess/density.hpp"
#include "scf/mean_field.hpp"
#include "scf/reference/linalg.hpp"
using namespace generativeqc;
using Clock=std::chrono::steady_clock;
double seconds(Clock::time_point a) {return std::chrono::duration<double>(Clock::now()-a).count();}
#include "basis.inc"
core::System system_for(const std::string& name) {
 core::System s; s.multiplicity=1;s.basis_representation=GENERATIVEQC_BASIS_CARTESIAN;
 s.atoms.push_back({8,{0,0,0}});
 if(name=="hydroxide-631g") {s.charge=-1;s.atoms.push_back({1,{0,0,1.8}});}
 else {const double k=name=="stretched-water-631g"?1.6:1.0;
  s.atoms.push_back({1,{0,-1.43233673*k,1.10715266*k}});
  s.atoms.push_back({1,{0,1.43233673*k,1.10715266*k}});}
 if(name=="water-dimer-631g") {s.atoms.push_back({8,{0,0,5.5}}); s.atoms.push_back({1,{0,-1.43233673,6.60715266}});s.atoms.push_back({1,{0,1.43233673,6.60715266}});}
 for(unsigned a=0;a<s.atoms.size();++a)
  if(name=="water-sto3g") add_sto(s,a,s.atoms[a].atomic_number);else add_split(s,a,s.atoms[a].atomic_number);
 std::string e;if(molecule::validate_and_normalize(s,e)!=GENERATIVEQC_STATUS_SUCCESS)throw std::runtime_error(e);
 return s;
}
void run(const std::string& name,const std::string& mode,const std::string& thermal) {
 const auto started=Clock::now(); auto s=system_for(name);
 auto spec=scf::make_global_hybrid_fock_spec(scf::FockSpin::Restricted,.25);spec.derivative_order=0;
 scf::PreparedFockPlan target(s,nullptr,scf::resolve_fock_build(spec,scf::FockBackend::Cpu));
 dft::AoBasis basis(s);dft::MolecularGrid grid(s,{1,24,12,24,3,1e-12});
 scf::ScfOptions opt;opt.compute_forces=false;opt.max_iterations=150;opt.energy_tolerance=1e-10;opt.density_tolerance=1e-8;
 opt.precision_mode=GENERATIVEQC_PRECISION_FP64;opt.semilocal_exchange_scale=.75;
 const double common_setup=seconds(started);
 std::vector<double> seed;double prep=0,cheap_setup=0,cheap_scf=0;unsigned cheap_iter=0;std::size_t cheap_fock=0;
 if(mode=="lda-coarse"||mode=="pbe-coarse") {
  auto prep_start=Clock::now();scf::FockBuildSpec cheap_spec;cheap_spec.derivative_order=0;cheap_spec.exchange.present=false;
  scf::PreparedFockPlan cheap(s,nullptr,scf::resolve_fock_build(cheap_spec,scf::FockBackend::Cpu));
  scf::ScfOptions co=opt;co.semilocal_exchange_scale=1;co.energy_tolerance=1e-6;co.density_tolerance=1e-4;
  dft::MolecularGrid cheap_grid(s,{1,8,6,12,3,1e-12});
  cheap_setup=seconds(prep_start);const auto scf_start=Clock::now();
  auto r=mode=="lda-coarse"?scf::run_lda_rks(cheap,basis,cheap_grid,co):scf::run_pbe_rks(cheap,basis,cheap_grid,co);
  cheap_scf=seconds(scf_start);if(!r.converged)throw std::runtime_error("cheap SCF failed");
  seed=std::move(r.density);cheap_iter=r.iterations;cheap_fock=r.fock_builds;prep=seconds(prep_start);
 } else if(mode=="xtb-charge") {
  const auto prep_start=Clock::now();std::vector<int32_t> z;std::vector<double> p;
  for(auto& a:s.atoms){z.push_back(a.atomic_number);p.insert(p.end(),a.position.begin(),a.position.end());}
  methods::detail::Gfn2RuntimeBridge runtime(methods::detail::Gfn2RuntimeBackend::kCpu,0);
  methods::detail::Gfn2RuntimeRequest q;q.atomic_numbers=z;q.positions=p;q.charge=s.charge;q.multiplicity=s.multiplicity;
  q.compute_atomic_charges=true;q.maximum_iterations=100;q.mixer_history=8;q.energy_tolerance=1e-10;q.charge_tolerance=1e-8;
  const auto scf_start=Clock::now();auto r=runtime.execute(q);cheap_scf=seconds(scf_start);
  if(r.status!=methods::detail::Gfn2RuntimeStatus::kSuccess||!r.converged)throw std::runtime_error("xTB failed: "+r.detail);
  cheap_iter=r.iterations;
  const auto& ints=target.one_electron();auto x=scf::reference::symmetric_orthogonalizer(ints.overlap,ints.nbf);
  std::optional<scf::reference::EigenResult> frame;
  auto core=scf::initial_guess::prepare_initial_density(s,ints,x,s.electron_count/2,nullptr,frame,scf::initial_guess::InitialOrbitalRequest::ColdDensityOnly);
  seed=scf::initial_guess::charge_guided_lowdin_density(s,ints,x,core,r.atomic_charges);
  prep=seconds(prep_start);cheap_setup=prep-cheap_scf;
 } else if(mode!="direct")throw std::runtime_error("bad mode");
 const auto scf_start=Clock::now();auto result=scf::run_pbe_rks(target,basis,grid,opt,seed.empty()?nullptr:&seed);
 const double target_scf=seconds(scf_start);const double total=seconds(started);
 if(!result.converged)throw std::runtime_error("target SCF failed");
 if(mode!="direct"&&!result.initial_density_used)throw std::runtime_error("seed not used");
 std::cout<<std::setprecision(17)<<"{\"case\":\""<<name<<"\",\"mode\":\""<<mode<<"\",\"thermal\":\""<<thermal<<"\",\"nao\":"<<target.one_electron().nbf<<",\"grid_points\":"<<grid.point_count()<<",\"common_setup_s\":"<<common_setup<<",\"prep_s\":"<<prep<<",\"cheap_setup_s\":"<<cheap_setup<<",\"cheap_scf_s\":"<<cheap_scf<<",\"target_scf_s\":"<<target_scf<<",\"total_s\":"<<total<<",\"cheap_iterations\":"<<cheap_iter<<",\"target_iterations\":"<<result.iterations<<",\"cheap_fock_builds\":"<<cheap_fock<<",\"target_fock_builds\":"<<result.fock_builds<<",\"energy\":"<<result.energy<<",\"residual\":"<<result.dft_diagnostic.physical_residual<<",\"density_change\":"<<result.dft_diagnostic.density_change<<",\"initial_density_used\":"<<result.initial_density_used<<",\"electrons\":"<<result.dft_diagnostic.electrons[0]<<",\"density\":[";
 for(std::size_t i=0;i<result.density.size();i++){if(i)std::cout<<',';std::cout<<result.density[i];}std::cout<<"]}"<<std::endl;
}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("case mode needed");run(argv[1],argv[2],"process-cold");run(argv[1],argv[2],"process-warm-fresh-context");}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
